WITH base AS (SELECT * FROM accounts WHERE customer_id IS NULL OR customer_id IS NOT NULL), accounts_stats AS (SELECT CASE WHEN balance >= 81000 THEN 'high' WHEN balance >= 19000 THEN 'mid' ELSE 'low' END balance_bucket, MIN(opened_date) min_opened_date, COUNT(*) num_accounts FROM base GROUP BY CASE WHEN balance >= 81000 THEN 'high' WHEN balance >= 19000 THEN 'mid' ELSE 'low' END) SELECT balance_bucket, min_opened_date, num_accounts FROM accounts_stats WHERE num_accounts >= 5 ORDER BY num_accounts;
